      this.socket.emitWebRTCEvents({
        event: 'SCREEN-SHARE-START',
        data: {
          from: this.nUserid,
          nPresentid: this.presentDetail.nPresentid,
          sfuConfig: this.sfuConfig
        },
        nToUserId: e
      });
